#!/usr/bin/env python3

"""
Check what the test expectation vs actual result looks like.
"""

import json
from dataclasses import dataclass, field
from typing import Optional, List
from mashumaro.jsonschema import build_json_schema
from mashumaro.jsonschema.models import (
    JSONObjectSchema, JSONArraySchema, JSONSchema, JSONSchemaInstanceType
)


@dataclass
class DataClass:
    a: int
    b: float = 3.14
    c: Optional[int] = field(default=None, metadata={"alias": "cc"})
    d: str = ""
    e: int = field(init=False)
    f: List[int] = field(
        default_factory=list, metadata={"description": "description for f"}
    )

    class Config:
        aliases = {"a": "aa", "d": "dd"}


def check_test_components():
    """Check what the test components look like."""

    # Build the expected schema (same as in the test)
    schema = JSONObjectSchema(
        title="DataClass",
        properties={
            "aa": JSONSchema(type=JSONSchemaInstanceType.INTEGER),
            "b": JSONSchema(type=JSONSchemaInstanceType.NUMBER, default=3.14),
            "cc": JSONSchema(
                anyOf=[
                    JSONSchema(type=JSONSchemaInstanceType.INTEGER),
                    JSONSchema(type=JSONSchemaInstanceType.NULL),
                ],
                default=None,
            ),
            "dd": JSONSchema(type=JSONSchemaInstanceType.STRING, default=""),
            "f": JSONArraySchema(
                items=JSONSchema(type=JSONSchemaInstanceType.INTEGER),
                description="description for f",
            ),
        },
        additionalProperties=False,
        required=["aa"],
    )

    print("Expected schema (without all_refs):")
    print(json.dumps(schema.to_dict(), indent=2))

    # Test the actual result with all_refs=True
    actual_result = build_json_schema(DataClass, all_refs=True)
    print("\nActual result with all_refs=True:")
    print(json.dumps(actual_result.to_dict(), indent=2))

    # Test what the test expects
    expected_result = JSONSchema(
        reference="#/defs/DataClass", definitions={"DataClass": schema}
    )
    print("\nTest expectation:")
    print(json.dumps(expected_result.to_dict(), indent=2))

    # Test what the test should expect with our fix
    corrected_expected_result = JSONSchema(
        reference="#/$defs/DataClass", definitions={"DataClass": schema}
    )
    print("\nCorrected expectation:")
    print(json.dumps(corrected_expected_result.to_dict(), indent=2))


if __name__ == "__main__":
    check_test_components()

